import 'package:flutter/material.dart';
import 'models.dart';

class DayboardColors {
  static const ink = Color(0xff171717), cream = Color(0xfffff8e8), pink = Color(0xffff77a8), yellow = Color(0xffffdc57), lilac = Color(0xffc9b6ff), mint = Color(0xff9ee6c1), blue = Color(0xff8dd9ff), orange = Color(0xffffa45b), green = Color(0xffb7e35f);
  static Color theme(DayTheme theme) => switch (theme) { DayTheme.pink => pink, DayTheme.yellow => yellow, DayTheme.lilac => lilac, DayTheme.mint => mint, DayTheme.blue => blue, DayTheme.orange => orange, DayTheme.green => green, DayTheme.cream => cream };
}

ThemeData dayboardTheme() => ThemeData(useMaterial3: true, scaffoldBackgroundColor: DayboardColors.cream, colorScheme: ColorScheme.fromSeed(seedColor: DayboardColors.pink, brightness: Brightness.light), fontFamily: 'Arial', textTheme: const TextTheme(bodyMedium: TextStyle(color: DayboardColors.ink, fontSize: 15), titleLarge: TextStyle(color: DayboardColors.ink, fontWeight: FontWeight.w900)), inputDecorationTheme: const InputDecorationTheme(border: OutlineInputBorder(borderSide: BorderSide(color: DayboardColors.ink, width: 3)), enabledBorder: OutlineInputBorder(borderSide: BorderSide(color: DayboardColors.ink, width: 3)), focusedBorder: OutlineInputBorder(borderSide: BorderSide(color: DayboardColors.ink, width: 4))));

class BrutalCard extends StatelessWidget { const BrutalCard({super.key, required this.child, this.color = DayboardColors.cream, this.padding = const EdgeInsets.all(16)}); final Widget child; final Color color; final EdgeInsets padding; @override Widget build(BuildContext context) => Container(padding: padding, decoration: BoxDecoration(color: color, border: Border.all(color: DayboardColors.ink, width: 3), boxShadow: const [BoxShadow(color: DayboardColors.ink, offset: Offset(5, 5))]), child: child); }
class BrutalButton extends StatelessWidget { const BrutalButton({super.key, required this.label, required this.onPressed, this.color = DayboardColors.yellow, this.icon}); final String label; final VoidCallback? onPressed; final Color color; final IconData? icon; @override Widget build(BuildContext context) => ElevatedButton.icon(onPressed: onPressed, icon: icon == null ? const SizedBox.shrink() : Icon(icon, color: DayboardColors.ink), label: Text(label, style: const TextStyle(color: DayboardColors.ink, fontWeight: FontWeight.w900)), style: ElevatedButton.styleFrom(backgroundColor: color, foregroundColor: DayboardColors.ink, shape: const RoundedRectangleBorder(borderRadius: BorderRadius.zero, side: BorderSide(color: DayboardColors.ink, width: 3)), padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 14), elevation: 0)); }
